import { t, locale, setLocale, bilingual, contentText, weekday, dateLocale, initLocale } from './i18n.js';

const $=(s,r=document)=>r.querySelector(s), main=$('#admin-main'), nav=$('#admin-nav'), title=$('#admin-title');
const state={me:null,bootstrap:null,tab:'home',people:null,services:null,churchProfile:null,contentTab:'news',songs:null,csrf:null};
const esc=(v='')=>String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const l=(en,es)=>locale()==='en'?en:es;
const fmtDate=iso=>new Intl.DateTimeFormat(dateLocale(),{weekday:'short',month:'short',day:'numeric',year:'numeric'}).format(new Date(`${iso}T12:00:00`));
const fmtTime=tm=>{const[h,m]=String(tm||'00:00').split(':').map(Number);return new Intl.DateTimeFormat(dateLocale(),{hour:'numeric',minute:'2-digit'}).format(new Date(2020,0,1,h,m));};
const dateParts=iso=>{const d=new Date(`${iso}T12:00:00`);return {month:new Intl.DateTimeFormat(dateLocale(),{month:'short'}).format(d).replace('.','').toUpperCase(),day:new Intl.DateTimeFormat(dateLocale(),{day:'2-digit'}).format(d),weekday:new Intl.DateTimeFormat(dateLocale(),{weekday:'long'}).format(d)};};
const dateTileHtml=iso=>{const d=dateParts(iso);return `<div class="date-tile"><span>${esc(d.month)}</span><strong>${esc(d.day)}</strong></div>`;};
async function api(url,opt={},_retry=true){const method=String(opt.method||'GET').toUpperCase();const csrf=(state.csrf&&['POST','PUT','PATCH','DELETE'].includes(method))?{'X-CSRF-Token':state.csrf}:{};const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json','X-Locale':locale(),...csrf,...(opt.headers||{})},...opt});const text=await r.text();let d={};try{d=text?JSON.parse(text):{};}catch{d={error:text};}if(!r.ok&&r.status===403&&d?.code==='CSRF_FAILED'&&_retry){try{const meResp=await fetch('/api/auth/me',{credentials:'same-origin',headers:{'X-Locale':locale()}});if(meResp.ok){const me=await meResp.json();state.me=me;state.csrf=me.csrfToken||null;return api(url,opt,false);}}catch{}state.csrf=null;}if(!r.ok){if(r.status===401&&d?.code==='AUTH_REQUIRED'){state.me=null;state.csrf=null;}throw new Error(d.error||t('error.requestFailed',{status:r.status}));}return d;}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.remove('hidden');setTimeout(()=>el.classList.add('hidden'),2800);}
function modal(html){$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-handle"></div>${html}</div></div>`;$('.modal-backdrop').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal();});}
function closeModal(){$('#modal-root').innerHTML='';}
function isOwner(){return state.me?.member?.churchAdministrator||state.me?.user?.churchAdministrator;}
function themeMode(){return localStorage.getItem('church-theme')||'system';}
function applyTheme(mode=themeMode(),persist=true){if(persist)localStorage.setItem('church-theme',mode);const dark=mode==='dark'||(mode==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';$('#theme-color')?.setAttribute('content',dark?'#08111f':'#f7f3ec');$('#admin-theme-btn').textContent=dark?'☀':'☾';}
async function savePreferences(){if(!state.me?.member)return;await api('/api/member/preferences',{method:'PUT',body:JSON.stringify({locale:locale(),theme:themeMode()})});}
function toggleTheme(){applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');savePreferences().catch(()=>{});}
applyTheme();

function applyBranding(){const church=state.bootstrap?.church||{};const name=locale()==='en'?(church.churchNameEn||church.churchName):(church.churchNameEs||church.churchName);$('#admin-church-name').textContent=name||'Church';const logoEl=$('#admin-logo'),logo=church.logoUrl||'';if(logoEl){if(logo){logoEl.src=logo;logoEl.classList.remove('hidden');}else logoEl.classList.add('hidden');}document.documentElement.style.setProperty('--accent',church.accentColor||'#2563eb');}
function bindHeaderControls(){const back=$('#admin-back-btn');if(back)back.onclick=()=>{window.location.assign('/');};const lang=$('#admin-language-btn');lang.textContent=locale()==='es'?'ES':'EN';lang.onclick=()=>{setLocale(locale()==='es'?'en':'es');savePreferences().catch(()=>{});renderAll();};$('#admin-theme-btn').onclick=toggleTheme;}
function tabs(){return[['home','🏠',t('common.home')],['people','👥',t('common.people')],['schedule','📅',t('common.schedule')],['content','📣',t('common.content')],['settings','⚙️',t('common.settings')]];}
function renderNav(){nav.innerHTML=tabs().map(([id,ico,label])=>`<button class="nav-btn ${state.tab===id?'active':''}" data-tab="${id}"><span class="ico">${ico}</span>${esc(label)}</button>`).join('');nav.querySelectorAll('button').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render();});}
async function init(){try{state.me=await api('/api/auth/me');state.csrf=state.me.csrfToken||null;if(!(state.me.member?.adminAccess||state.me.user?.adminAccess||state.me.user?.churchAdministrator))throw new Error(t('error.admin'));state.bootstrap=await api('/api/public/bootstrap');initLocale(state.bootstrap.church?.defaultLocale||'es');if(state.me?.member?.preferences?.locale)setLocale(state.me.member.preferences.locale,false);if(state.me?.member?.preferences?.theme)applyTheme(state.me.member.preferences.theme);state.bootstrap=await api('/api/public/bootstrap');applyBranding();bindHeaderControls();renderNav();render();}catch{location.href='/';}}
function renderAll(){applyBranding();bindHeaderControls();renderNav();render();}
function render(){const current=tabs().find(x=>x[0]===state.tab);title.textContent=current?.[2]||t('common.admin');if(state.tab==='home')return home();if(state.tab==='people')return people();if(state.tab==='schedule')return schedule();if(state.tab==='content')return content();if(state.tab==='settings')return settings();}

async function home(){main.innerHTML=`<div class="card empty">${t('common.loading')}</div>`;try{const d=await api('/api/admin/dashboard');const hasIssues=d.unfilled.length||d.missingSongs;main.innerHTML=`<div class="admin-hero"><div><div class="eyebrow">${t('admin.dashboard')}</div><h2>${t('admin.attention')}</h2><p class="muted small">${t('admin.attentionHelp')}</p></div><span class="status-orb ${hasIssues?'warn':'good'}">${hasIssues?'!':'✓'}</span></div><div class="stack">${d.unfilled.length?`<div class="attention action-attention"><span class="ico">⚠</span><div><strong>${t('admin.openAssignments',{count:d.unfilled.length})}</strong><div class="small">${t('admin.noEligible')}</div></div></div>`:''}${d.missingSongs?`<div class="attention songs-attention"><span class="ico">♫</span><div><strong>${t('admin.missingSongs',{count:d.missingSongs})}</strong><div class="small">${t('admin.missingSongsHelp')}</div></div></div>`:''}${!hasIssues?`<div class="ready-banner"><span>✓</span><div><strong>${t('admin.coverageGood')}</strong><small>${t('admin.readyMeansComplete')}</small></div></div>`:''}${d.newVisitors?`<div class="attention"><span class="ico">♡</span><div><strong>${t('admin.newVisitors',{count:d.newVisitors})}</strong></div></div>`:''}${d.newPetitions?`<div class="attention"><span class="ico">♡</span><div><strong>${t('admin.newPetitions',{count:d.newPetitions})}</strong></div></div>`:''}</div><div class="section-title"><h3>${t('admin.quickActions')}</h3></div><div class="button-grid"><button class="btn secondary quick" data-go="people"><strong>${t('admin.addMember')}</strong><span>${t('admin.peopleMinistries')}</span></button><button class="btn secondary quick" id="quick-generate"><strong>${t('admin.generate')}</strong><span>${t('admin.currentTwoWeeks')}</span></button><button class="btn secondary quick" data-go="content"><strong>${t('admin.postNews')}</strong><span>${t('admin.announcement')}</span></button><button class="btn secondary quick" data-go="content"><strong>${t('admin.uploadBulletin')}</strong><span>${t('admin.pdfImage')}</span></button></div><div class="section-title"><h3>${t('admin.upcomingServices')}</h3></div>${d.programs.slice(0,6).map(programCard).join('')}`;main.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.go;render();});$('#quick-generate').onclick=generateSchedule;bindAssignmentEditors();}catch(e){main.innerHTML=`<div class="attention">${esc(e.message)}</div>`;}}
async function generateSchedule(){try{toast(t('admin.generating'));const r=await api('/api/admin/schedule/generate',{method:'POST'});toast(t('admin.generated',{count:r.programCount}));if(state.tab==='schedule')schedule();else if(state.tab==='home')home();}catch(e){toast(e.message);}}
function songsHtml(songs=[]){return songs.length?`<div class="selected-songs">${songs.map(s=>`<div class="song-line"><strong>${esc(s.number||'♪')}</strong><span>${esc(locale()==='en'?(s.titleEn||s.titleEs||s.title):(s.titleEs||s.title||s.titleEn))}</span></div>`).join('')}</div>`:'';}
function programCard(p){const open=Number(p.readiness?.openAssignments??(p.items||[]).flatMap(i=>i.assignees||[]).filter(a=>!a.memberId).length),missingSongs=Number(p.readiness?.missingSongs||0),ready=p.readiness?.ready??(open===0&&missingSongs===0),dp=dateParts(p.dateISO);const status=ready?`<span class="badge success">✓ ${t('common.ready')}</span>`:missingSongs&&!open?`<span class="badge warn">♫ ${t('schedule.needsSongs')}</span>`:`<span class="badge warn">${open?`${open} ${t('common.open')}`:t('schedule.needsAttention')}</span>`;return `<div class="card service-card modern-program ${ready?'program-ready':'program-incomplete'}"><div class="program-date-band">${dateTileHtml(p.dateISO)}<div class="grow"><div class="service-name">${esc(bilingual(p.service)||p.serviceId)}</div><div class="small muted">${esc(dp.weekday)} · ${fmtTime(p.startTime)}</div></div>${status}</div>${missingSongs?`<div class="program-warning-strip">♫ ${t('schedule.missingSongAssignments',{count:missingSongs})}</div>`:''}<div class="program-lines">${(p.items||[]).map(i=>`<div class="assignment"><div class="grow"><div class="assignment-label">${esc(bilingual(i))}</div>${(i.assignees||[]).map((a,idx)=>`<div class="program-person-row"><div class="grow"><div class="assignment-name ${!a.memberId?'unfilled-name':''}">${!a.memberId?`${idx+1}. ${t('share.unfilled')}`:esc(a.fullName)}</div>${i.linked?'':songsHtml(a.songs)}${a.ministryId==='ministry_songs'&&a.memberId&&!a.songs?.length&&!i.linked?`<div class="tiny needs-songs-note">♫ ${t('schedule.songsNeedAttention')}</div>`:''}</div>${a.assignmentId?`<button class="row-menu edit-assignment" data-assignment="${esc(a.assignmentId)}" aria-label="${esc(t('common.change'))}">•••</button>`:''}</div>`).join('')}</div></div>`).join('')}</div></div>`;}
async function editAssignment(assignmentId){try{const d=await api(`/api/admin/schedule/assignments/${encodeURIComponent(assignmentId)}/candidates`);const eligibleIds=new Set(d.candidates.map(c=>c.memberId));modal(`<div class="modal-header"><div><div class="eyebrow">${t('admin.smartFairEligible')}</div><h2>${t('admin.changeAssignment')}</h2></div><button class="icon-btn compact" id="close-modal">×</button></div><p class="muted small">${t('admin.candidateHelp')}</p><div class="stack">${d.candidates.map(c=>`<button class="candidate-card candidate-choice" data-member="${esc(c.memberId)}"><span class="candidate-avatar">${esc((c.fullName||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join(''))}</span><span class="grow"><strong>${esc(c.fullName)}</strong><small>Smart Fair ${Number(c.score?.final||0).toFixed(1)}</small></span><span>›</span></button>`).join('')||`<div class="empty compact-empty">${t('admin.noEligibleOthers')}</div>`}</div><div class="override-zone"><div><strong>${t('admin.manualOverride')}</strong><p class="tiny muted">${t('admin.manualOverrideHelp')}</p></div><button class="btn secondary full" id="show-override">${t('admin.assignAnyMember')}</button><div id="override-list" class="stack hidden"></div></div>`);$('#close-modal').onclick=closeModal;document.querySelectorAll('.candidate-choice').forEach(b=>b.onclick=()=>saveAssignmentChoice(assignmentId,b.dataset.member,false));$('#show-override').onclick=()=>{const list=$('#override-list');list.classList.remove('hidden');$('#show-override').classList.add('hidden');list.innerHTML=`<input class="input" id="override-search" placeholder="${esc(t('admin.searchMembers'))}"><div id="override-results" class="stack"></div>`;const draw=()=>{const q=($('#override-search').value||'').toLowerCase().trim();const rows=(d.overrideCandidates||[]).filter(m=>!q||String(m.fullName||'').toLowerCase().includes(q));$('#override-results').innerHTML=rows.map(m=>`<button class="candidate-card override-choice" data-member="${esc(m.memberId)}" data-name="${esc(m.fullName)}"><span class="candidate-avatar neutral">${esc((m.fullName||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join(''))}</span><span class="grow"><strong>${esc(m.fullName)}</strong><small>${eligibleIds.has(m.memberId)?t('admin.normallyEligible'):t('admin.outsideMinistry')}</small></span><span>›</span></button>`).join('');document.querySelectorAll('.override-choice').forEach(b=>b.onclick=async()=>{if(!eligibleIds.has(b.dataset.member)&&!confirm(t('admin.overrideConfirm',{name:b.dataset.name})))return;await saveAssignmentChoice(assignmentId,b.dataset.member,true);});};$('#override-search').oninput=draw;draw();};}catch(e){toast(e.message);}}
async function saveAssignmentChoice(assignmentId,memberId,override){try{await api(`/api/admin/schedule/assignments/${encodeURIComponent(assignmentId)}`,{method:'PUT',body:JSON.stringify({memberId,locked:true,override})});toast(override?t('admin.overrideSaved'):t('admin.assignmentChanged'));closeModal();render();}catch(e){toast(e.message);}}
function bindAssignmentEditors(){main.querySelectorAll('.edit-assignment').forEach(b=>b.onclick=()=>editAssignment(b.dataset.assignment));}

async function people(){main.innerHTML=`<div class="card empty">${t('people.loading')}</div>`;try{state.people=await api('/api/admin/people');main.innerHTML=`<div class="button-grid"><a class="btn secondary" href="/api/admin/people/export?format=csv" target="_blank">${t('people.exportCsv')}</a><a class="btn secondary" href="/api/admin/people/export?format=excel" target="_blank">${t('people.exportExcel')}</a><a class="btn secondary" href="/api/admin/people/export?format=pdf" target="_blank">${t('people.exportPdf')}</a></div><div class="row"><input class="input grow" id="people-search" placeholder="${esc(t('people.search'))}"><button class="btn" id="add-person">+ ${t('common.add')}</button></div>${isOwner()?`<div class="card flat row between" style="margin-top:12px"><div><strong>${t('imports.membersTitle')}</strong><div class="tiny muted">${t('imports.membersShort')}</div></div><button class="btn secondary" id="bulk-member-import">${t('imports.import')}</button></div>`:''}<div class="card" id="people-list"></div>`;$('#people-search').oninput=renderPeopleList;$('#add-person').onclick=()=>personModal(null);$('#bulk-member-import')?.addEventListener('click',memberImportModal);renderPeopleList();}catch(e){main.innerHTML=`<div class="attention">${esc(e.message)}</div>`;}}
function renderPeopleList(){const q=($('#people-search')?.value||'').toLowerCase();const items=(state.people?.members||[]).filter(m=>!q||m.fullName.toLowerCase().includes(q)||String(m.username||'').includes(q));$('#people-list').innerHTML=items.map(m=>`<div class="person-row row tap" data-id="${m.id}"><div class="avatar">${esc(m.fullName.split(/\s+/).slice(0,2).map(x=>x[0]).join(''))}</div><div class="grow"><strong>${esc(m.fullName)}</strong><div class="small muted">${esc((m.groups||[]).map(g=>g==='members'?t('common.member'):g==='worship'?t('common.worship'):g).join(' · '))}${m.adminAccess?` · ${t('common.admin')}`:''}</div></div><span>›</span></div>`).join('')||`<div class="empty">${t('people.noPeople')}</div>`;$('#people-list').querySelectorAll('[data-id]').forEach(x=>x.onclick=()=>personModal(state.people.members.find(m=>m.id===x.dataset.id)));}
function personModal(member){
  const isNew=!member;
  member=member||{fullName:'',username:'',email:'',phone:'',active:true,groups:['members'],ministries:[],serviceAvailability:[],allowSameDayMultipleServices:false,notificationPreferences:{sms:true,email:true,push:true},childrenProgramEnabled:false,childrenWorkerRoles:[]};
  const ministries=state.people.ministries||[],services=state.people.services||[],workerRoles=Array.isArray(member.childrenWorkerRoles)?member.childrenWorkerRoles:[];
  modal(`<div class="modal-header"><div><div class="eyebrow">${l('Member profile','Perfil del miembro')}</div><h2>${isNew?t('people.addMember'):esc(member.fullName)}</h2></div><button class="icon-btn compact" id="close-modal">×</button></div>
  <form id="person-form" class="stack member-profile-form">
    <section class="profile-panel"><div class="profile-panel-title"><span>👤</span><div><strong>${l('Identity & contact','Identidad y contacto')}</strong><small>${l('Keep contact information even when delivery channels are turned off.','Conserva la información de contacto aunque se desactiven canales de entrega.')}</small></div></div>
      <div class="field"><label>${t('common.name')}</label><input class="input" name="fullName" value="${esc(member.fullName)}" required></div>
      <div class="field"><label>${t('common.username')}</label><input class="input" name="username" value="${esc(member.username||'')}"></div>
      <div class="field"><label>${t('common.email')}</label><input class="input" name="email" type="email" value="${esc(member.email||'')}"></div>
      <div class="field"><label>${t('common.phone')}</label><input class="input" name="phone" inputmode="tel" value="${esc(member.phone||'')}"></div>
      <div class="check-grid"><label class="check-row"><input type="checkbox" name="notify_sms" ${member.notificationPreferences?.sms!==false?'checked':''}> ${l('Text notifications','Notificaciones por texto')}</label><label class="check-row"><input type="checkbox" name="notify_email" ${member.notificationPreferences?.email!==false?'checked':''}> ${l('Email notifications','Notificaciones por correo')}</label></div>
    </section>
    <section class="profile-panel children-staff-panel"><div class="profile-panel-title"><span>🧸</span><div><strong>${l("Children's Ministry","Ministerio de Niños")}</strong><small>${l('Family enrollment and staff portal access are controlled separately.','El registro familiar y el acceso del personal se controlan por separado.')}</small></div></div>
      <label class="check-row"><input type="checkbox" name="childrenProgramEnabled" ${member.childrenProgramEnabled===true?'checked':''}> <span><strong>${l("Family enrolled in Children's Check-in",'Familia registrada en el módulo de niños')}</strong><small>${l('Shows family check-in tools in this member’s app.','Muestra las herramientas familiares de registro en su aplicación.')}</small></span></label>
      <div class="tiny muted">${l('Child-care worker portal access','Acceso al portal de cuidadores')}</div>
      <div class="check-grid"><label class="check-row role-check"><input type="checkbox" name="childrenWorkerRole" value="nursery" ${workerRoles.includes('nursery')?'checked':''}> <span>🍼 <strong>${l('Nursery worker','Cuidador de Nursery')}</strong></span></label><label class="check-row role-check"><input type="checkbox" name="childrenWorkerRole" value="toddlers" ${workerRoles.includes('toddlers')?'checked':''}> <span>🧩 <strong>${l('Toddler worker','Cuidador de Toddlers')}</strong></span></label></div>
    </section>
    <section class="profile-panel"><div class="profile-panel-title"><span>🔐</span><div><strong>${l('Access & ministry eligibility','Acceso y elegibilidad ministerial')}</strong></div></div>
      <label class="check-row"><input type="checkbox" name="active" ${member.active!==false?'checked':''}> ${t('common.active')}</label>
      <div class="check-grid"><label class="check-row"><input type="checkbox" name="group_members" ${(member.groups||[]).includes('members')?'checked':''}> ${t('common.member')}</label><label class="check-row"><input type="checkbox" name="group_worship" ${(member.groups||[]).includes('worship')?'checked':''}> ${t('common.worship')}</label></div>
      <h3>${t('people.ministries')}</h3><div class="check-grid">${ministries.filter(x=>x.active!==false).map(x=>`<label class="check-row"><input type="checkbox" name="ministry" value="${x.id}" ${(member.ministries||[]).includes(x.id)?'checked':''}> ${esc(bilingual(x))}</label>`).join('')}</div>
      <h3>${t('people.serviceAvailability')}</h3><div class="check-grid">${services.filter(x=>x.active!==false).map(x=>`<label class="check-row"><input type="checkbox" name="service" value="${x.id}" ${(member.serviceAvailability||[]).includes(x.id)?'checked':''}> ${esc(bilingual(x))} · ${fmtTime(x.startTime)}</label>`).join('')}</div>
      <label class="check-row"><input type="checkbox" name="sameDay" ${member.allowSameDayMultipleServices?'checked':''}><span><strong>${t('people.sameDay')}</strong><div class="tiny muted">${t('people.sameDayHelp')}</div></span></label>
      ${!isNew&&isOwner()&&!member.churchAdministrator?`<label class="check-row"><input type="checkbox" name="adminAccess" ${member.adminAccess?'checked':''}><span><strong>${t('people.adminAccess')}</strong><div class="tiny muted">${t('people.adminAccessHelp')}</div></span></label>`:''}
    </section>
    <button class="btn full">${t('common.save')}</button>${!isNew?`<button type="button" class="btn secondary full" id="provision-account">${t('people.resetPassword')}</button>`:''}
  </form>`);
  $('#close-modal').onclick=closeModal;
  $('#person-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),groups=[];if(f.get('group_members'))groups.push('members');if(f.get('group_worship'))groups.push('worship');const payload={fullName:f.get('fullName'),username:f.get('username'),email:f.get('email'),phone:f.get('phone'),active:!!f.get('active'),groups,ministries:f.getAll('ministry'),serviceAvailability:f.getAll('service'),allowSameDayMultipleServices:!!f.get('sameDay'),notificationPreferences:{sms:!!f.get('notify_sms'),email:!!f.get('notify_email'),push:member.notificationPreferences?.push!==false},childrenProgramEnabled:!!f.get('childrenProgramEnabled'),childrenWorkerRoles:f.getAll('childrenWorkerRole').filter(x=>['nursery','toddlers'].includes(x))};try{if(isNew)await api('/api/admin/people',{method:'POST',body:JSON.stringify(payload)});else await api(`/api/admin/people/${member.id}`,{method:'PUT',body:JSON.stringify(payload)});if(!isNew&&isOwner()&&!member.churchAdministrator&&!!f.get('adminAccess')!==!!member.adminAccess)await api(`/api/owner/people/${member.id}/admin-access`,{method:'PUT',body:JSON.stringify({adminAccess:!!f.get('adminAccess')})});toast(t('people.saved'));closeModal();people();}catch(err){toast(err.message);}};
  $('#provision-account')?.addEventListener('click',async()=>{const password=prompt(t('people.tempPasswordPrompt'));if(!password)return;try{await api(`/api/admin/people/${member.id}/provision-account`,{method:'POST',body:JSON.stringify({username:$('[name="username"]',$('#person-form')).value,password,mustChangePassword:true})});toast(t('people.loginUpdated'));}catch(err){toast(err.message);}});
}

async function schedule(){main.innerHTML=`<div class="card empty">${t('common.loading')}</div>`;try{const programs=await api('/api/admin/schedule/programs');main.innerHTML=`<div class="row between"><div><h2>${t('adminSchedule.title')}</h2><div class="small muted">${t('adminSchedule.subtitle')}</div></div><button class="btn" id="generate">${t('adminSchedule.generate')}</button></div>${programs.map(programCard).join('')}<div class="section-title"><h3>${t('history.title')}</h3><button class="btn secondary" id="view-history">${t('history.view')}</button></div>`;$('#generate').onclick=generateSchedule;$('#view-history').onclick=historyModal;bindAssignmentEditors();}catch(e){main.innerHTML=`<div class="attention">${esc(e.message)}</div>`;}}
async function historyModal(){try{const [rows,p]=await Promise.all([api('/api/admin/history?max=250'),state.people||api('/api/admin/people')]);state.people=p;const names=new Map(p.members.map(m=>[m.id,m.fullName]));modal(`<div class="modal-header"><h2>${t('history.title')}</h2><button class="icon-btn compact" id="close-modal">×</button></div><div class="timeline">${rows.filter(r=>r.eventType!=='scheduler.decision').map(r=>`<div class="timeline-item"><div class="timeline-mark"><span class="timeline-dot"></span><span class="timeline-line"></span></div><div class="timeline-body"><strong>${esc(t(`event.${r.eventType}`))}</strong><div class="small">${esc(names.get(r.memberId)||r.memberId||t('history.system'))}</div><div class="tiny muted">${esc(r.dateISO||'')} · ${esc(ministryDisplay(r.ministryId))}</div>${r.penaltyEligible?`<span class="badge warn">${t('history.currentWeek')}</span>`:''}</div></div>`).join('')||`<div class="empty">${t('history.empty')}</div>`}</div>`);$('#close-modal').onclick=closeModal;}catch(e){toast(e.message);}}
function ministryDisplay(id){const m=state.people?.ministries?.find(x=>x.id===id)||state.services?.ministries?.find(x=>x.id===id);return m?bilingual(m):(id||'');}

async function content(){main.innerHTML=`<div class="card empty">${t('common.loading')}</div>`;try{const [items,visitors,petitions,songs]=await Promise.all([api('/api/admin/content'),api('/api/admin/visitors'),api('/api/admin/petitions'),api('/api/admin/songs')]);state.songs=songs;const tabsHtml=`<div class="pill-tabs" id="content-tabs"><button class="pill ${state.contentTab==='news'?'active':''}" data-content-tab="news">${t('content.news')}</button><button class="pill ${state.contentTab==='songs'?'active':''}" data-content-tab="songs">${t('content.songs')}</button><button class="pill ${state.contentTab==='inbox'?'active':''}" data-content-tab="inbox">${t('content.inbox')}</button></div>`;let body='';if(state.contentTab==='songs'){body=`<div class="section-title"><div><h3>${t('content.songLibrary')}</h3><div class="small muted">${t('content.songCount',{count:songs.length})}</div></div><button class="btn" id="add-song">${t('content.addSong')}</button></div>${isOwner()?`<div class="button-grid"><a class="btn secondary" href="/api/owner/songs/export?format=csv" target="_blank">${t('imports.exportCsv')}</a><a class="btn secondary" href="/api/owner/songs/export?format=excel" target="_blank">${t('imports.exportExcel')}</a><button class="btn secondary" id="import-songs">${t('imports.importSongs')}</button></div>`:''}<input class="input" id="song-search" placeholder="${esc(t('content.searchSongs'))}"><div class="card" id="song-list" style="margin-top:12px"></div>`;}else if(state.contentTab==='inbox'){body=`<div class="section-title"><h3>${t('content.visitorContacts')}</h3><span class="badge">${visitors.filter(v=>v.status==='new').length} ${t('common.new')}</span></div><div class="stack">${visitors.sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||''))).map(v=>`<div class="card"><div class="row between"><strong>${esc(v.fullName||t('content.visitorContacts'))}</strong>${v.kind==='member_access_request'?`<span class="badge">${t('login.requestAccess')}</span>`:''}<span class="badge ${v.status==='new'?'warn':''}">${esc(v.status||'new')}</span></div><div class="small muted">${esc(v.phone||'')}${v.phone&&v.email?' · ':''}${esc(v.email||'')}</div>${v.prayerRequest?`<p class="small">${esc(v.prayerRequest)}</p>`:''}${v.kind==='member_access_request'&&v.status==='new'?`<div class="button-grid" style="margin-top:10px"><button class="btn" data-access-approve="${esc(v.id)}">${t('people.approveAccess')}</button><button class="btn secondary" data-access-reject="${esc(v.id)}">${t('people.rejectAccess')}</button></div>`:''}${v.kind==='member_access_request'&&v.status==='approved'?`<div class="tiny muted">${t('people.profileCreated')}</div>`:''}</div>`).join('')||`<div class="card empty">${t('content.noVisitors')}</div>`}</div><div class="section-title"><h3>${t('content.petitions')}</h3><span class="badge">${petitions.filter(p=>p.status==='new').length} ${t('common.new')}</span></div><div class="stack">${petitions.sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||''))).map(p=>`<div class="card"><div class="row between"><strong>${esc(p.memberName||t('common.member'))}</strong>${p.private?`<span class="badge warn">${t('common.private')}</span>`:''}</div><p class="small">${esc(p.text||'')}</p></div>`).join('')||`<div class="card empty">${t('content.noPetitions')}</div>`}</div>`;}else{body=`<div class="button-grid"><button class="btn secondary quick" id="new-news"><strong>${t('content.newAnnouncement')}</strong><span>${t('content.newsMembers')}</span></button><button class="btn secondary quick" id="new-bulletin"><strong>${t('content.newBulletin')}</strong><span>${t('content.uploadFile')}</span></button></div><div class="section-title"><h3>${t('content.published')}</h3></div><div class="stack">${items.sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt))).map(x=>`<div class="card"><div class="row between"><span class="badge">${esc(x.kind)}</span><button class="btn ghost" data-delete="${x.id}">${t('common.delete')}</button></div><h3>${esc(contentText(x,'title'))}</h3><p class="muted">${esc(contentText(x,'body'))}</p></div>`).join('')||`<div class="card empty">${t('content.noContent')}</div>`}</div>`;}main.innerHTML=tabsHtml+body;main.querySelectorAll('[data-content-tab]').forEach(b=>b.onclick=()=>{state.contentTab=b.dataset.contentTab;content();});if(state.contentTab==='songs'){$('#song-search').oninput=renderSongList;$('#add-song').onclick=()=>songModal(null);$('#import-songs')?.addEventListener('click',songImportModal);renderSongList();}else if(state.contentTab==='inbox'){main.querySelectorAll('[data-access-approve]').forEach(b=>b.onclick=async()=>{if(!confirm(t('people.approveConfirm')))return;try{const r=await api(`/api/admin/member-access/${b.dataset.accessApprove}/approve`,{method:'POST'});toast(t('people.approved'));state.people=null;content();}catch(err){toast(err.message);}});main.querySelectorAll('[data-access-reject]').forEach(b=>b.onclick=async()=>{if(!confirm(t('people.rejectConfirm')))return;try{await api(`/api/admin/member-access/${b.dataset.accessReject}/reject`,{method:'POST',body:'{}'});toast(t('people.rejected'));content();}catch(err){toast(err.message);}});}else if(state.contentTab==='news'){$('#new-news').onclick=()=>contentModal('announcement');$('#new-bulletin').onclick=()=>contentModal('bulletin');main.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm(t('content.deleteConfirm')))return;await api(`/api/admin/content/${b.dataset.delete}`,{method:'DELETE'});content();});}}catch(e){main.innerHTML=`<div class="attention">${esc(e.message)}</div>`;}}
function renderSongList(){const target=$('#song-list');if(!target)return;const q=($('#song-search')?.value||'').trim().toLowerCase();const songs=(state.songs||[]).filter(s=>!q||String(s.number||'').toLowerCase().includes(q)||String(s.titleEs||s.title||'').toLowerCase().includes(q)||String(s.titleEn||'').toLowerCase().includes(q)).sort((a,b)=>Number(a.number)-Number(b.number));target.innerHTML=songs.map(s=>`<button class="person-row row tap full song-row" data-song="${esc(s.id)}"><div class="avatar">${esc(s.number||'♪')}</div><div class="grow" style="text-align:left"><strong>${esc(locale()==='en'?(s.titleEn||s.titleEs||s.title):(s.titleEs||s.title||s.titleEn))}</strong><div class="small muted">${s.active===false?t('common.inactive'):t('content.hymn',{number:s.number||''})}</div></div><span>›</span></button>`).join('')||`<div class="empty">${t('content.noSongs')}</div>`;target.querySelectorAll('[data-song]').forEach(b=>b.onclick=()=>songModal((state.songs||[]).find(s=>s.id===b.dataset.song)));}
function songModal(song){const isNew=!song;song=song||{number:'',titleEs:'',titleEn:'',active:true};modal(`<div class="modal-header"><h2>${isNew?t('content.addSongTitle'):t('content.editSong')}</h2><button class="icon-btn compact" id="close-modal">×</button></div><form id="song-form" class="stack"><div class="field"><label>${t('content.hymnNumber')}</label><input class="input" name="number" inputmode="numeric" value="${esc(song.number||'')}"></div><div class="field"><label>${t('content.titleSpanish')}</label><input class="input" name="titleEs" value="${esc(song.titleEs||song.title||'')}" required></div><div class="field"><label>${t('content.titleEnglish')}</label><input class="input" name="titleEn" value="${esc(song.titleEn||'')}"></div><label class="check-row"><input type="checkbox" name="active" ${song.active!==false?'checked':''}> ${t('common.active')}</label><button class="btn full">${isNew?t('content.addSongTitle'):t('common.save')}</button></form>`);$('#close-modal').onclick=closeModal;$('#song-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),payload={number:f.get('number'),titleEs:f.get('titleEs'),titleEn:f.get('titleEn'),active:f.get('active')==='on'};try{if(isNew)await api('/api/admin/songs',{method:'POST',body:JSON.stringify(payload)});else await api(`/api/admin/songs/${encodeURIComponent(song.id)}`,{method:'PUT',body:JSON.stringify(payload)});toast(isNew?t('content.songAdded'):t('content.songSaved'));closeModal();content();}catch(err){toast(err.message);}};}
function contentModal(kind){modal(`<div class="modal-header"><h2>${kind==='bulletin'?t('content.uploadBulletin'):t('content.postAnnouncement')}</h2><button class="icon-btn compact" id="close-modal">×</button></div><form id="content-form" class="stack"><div class="field"><label>${t('content.titleSpanish')}</label><input class="input" name="titleEs" required></div><div class="field"><label>${t('content.titleEnglish')}</label><input class="input" name="titleEn"></div><div class="field"><label>${t('content.messageSpanish')}</label><textarea class="textarea" name="bodyEs"></textarea></div><div class="field"><label>${t('content.messageEnglish')}</label><textarea class="textarea" name="bodyEn"></textarea></div>${kind==='announcement'?`<div class="field"><label>${t('content.activityAddress')}</label><input class="input" name="address" placeholder="123 Main St, Houston, TX"><div class="tiny muted">${t('content.activityAddressHelp')}</div></div>`:''}${kind==='bulletin'?`<div class="field"><label>${t('content.bulletinFile')}</label><input class="input" type="file" name="file" accept="application/pdf,image/jpeg,image/png" required></div>`:`<div class="field"><label>${t('content.attachment')} (${t('common.optional')})</label><input class="input" type="file" name="file" accept="application/pdf,image/jpeg,image/png"></div>`}<button class="btn full">${t('common.publish')}</button></form>`);$('#close-modal').onclick=closeModal;$('#content-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),file=f.get('file');let filePayload=null;if(file&&file.size)filePayload={fileName:file.name,contentType:file.type,base64:await fileToDataUrl(file)};try{await api('/api/admin/content',{method:'POST',body:JSON.stringify({kind,titleEs:f.get('titleEs'),titleEn:f.get('titleEn'),bodyEs:f.get('bodyEs'),bodyEn:f.get('bodyEn'),address:f.get('address')||'',file:filePayload})});toast(t('content.publishedSuccess'));closeModal();content();}catch(err){toast(err.message);}};}
function fileToDataUrl(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});}

async function settings(){main.innerHTML=`<div class="card empty">${t('common.loading')}</div>`;try{const [serviceData,profile]=await Promise.all([api('/api/admin/services'),api('/api/admin/church-profile')]);state.services=serviceData;state.churchProfile=profile;main.innerHTML=`<div class="section-title"><h3>${t('settings.churchProfile')}</h3><button class="btn secondary" id="edit-church-profile">${t('common.edit')}</button></div><div class="card row">${state.bootstrap?.church?.logoUrl?`<img class="church-logo-preview" style="max-width:150px;max-height:70px" src="${esc(state.bootstrap.church.logoUrl)}" alt="">`:''}<div class="grow"><strong>${esc(locale()==='en'?(profile.churchNameEn||profile.churchName):(profile.churchNameEs||profile.churchName))}</strong></div></div><div class="section-title"><h3>${t('settings.services')}</h3><button class="btn" id="add-service">${t('settings.addService')}</button></div><div class="stack">${state.services.services.sort((a,b)=>(a.recurrence?.weekday||0)-(b.recurrence?.weekday||0)||a.startTime.localeCompare(b.startTime)).map(s=>`<div class="card tap" data-service="${s.id}"><div class="row between"><div><strong>${esc(bilingual(s))}</strong><div class="small muted">${esc(weekday(s.recurrence?.weekday||0))} · ${fmtTime(s.startTime)}</div></div><span>›</span></div></div>`).join('')}</div>${isOwner()?`<div class="section-title"><h3>${t('settings.churchAdmin')}</h3></div><div class="card stack"><button class="btn secondary full" id="advanced">${t('settings.advanced')}</button><button class="btn secondary full" id="audit">${t('settings.audit')}</button><button class="btn secondary full" id="reports">${l('Leadership Reports','Reportes de Liderazgo')}</button><button class="btn secondary full" id="children-admin">${l("Children's Check-in","Registro de niños")}</button><button class="btn secondary full" id="communications">${t('settings.communications')}</button><button class="btn secondary full" id="bulk-imports">${t('imports.title')}</button></div>`:''}`;$('#edit-church-profile').onclick=churchProfileModal;$('#add-service').onclick=()=>serviceModal(null);main.querySelectorAll('[data-service]').forEach(x=>x.onclick=()=>serviceModal(state.services.services.find(s=>s.id===x.dataset.service)));$('#advanced')?.addEventListener('click',advancedModal);$('#audit')?.addEventListener('click',auditModal);$('#reports')?.addEventListener('click',reportsModal);$('#children-admin')?.addEventListener('click',childrenAdminModal);$('#communications')?.addEventListener('click',communicationsModal);$('#bulk-imports')?.addEventListener('click',bulkImportsModal);}catch(e){main.innerHTML=`<div class="attention">${esc(e.message)}</div>`;}}
function churchProfileModal(){const c=state.churchProfile||{};modal(`<div class="modal-header"><h2>${t('settings.churchProfile')}</h2><button class="icon-btn compact" id="close-modal">×</button></div><form id="church-profile-form" class="stack">${state.bootstrap?.church?.logoUrl?`<img class="church-logo-preview" src="${esc(state.bootstrap.church.logoUrl)}" alt="">`:''}<div class="field"><label>${t('settings.churchName')} (Español)</label><input class="input" name="churchNameEs" value="${esc(c.churchNameEs||c.churchName||'')}" required></div><div class="field"><label>${t('settings.churchName')} (English)</label><input class="input" name="churchNameEn" value="${esc(c.churchNameEn||c.churchName||'')}" required></div><div class="field"><label>${t('settings.logo')}</label><input class="input" type="file" name="logo" accept="image/png,image/jpeg,image/webp"><div class="tiny muted">${t('settings.logoHelp')}</div></div><div class="field"><label>${t('settings.accent')}</label><input class="input" type="color" name="accentColor" value="${esc(c.accentColor||'#2563eb')}"></div><button class="btn full">${t('settings.saveProfile')}</button></form>`);$('#close-modal').onclick=closeModal;$('#church-profile-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),file=f.get('logo');let logo=null;if(file&&file.size)logo={fileName:file.name,contentType:file.type,base64:await fileToDataUrl(file)};try{await api('/api/admin/church-profile',{method:'PUT',body:JSON.stringify({churchNameEs:f.get('churchNameEs'),churchNameEn:f.get('churchNameEn'),churchName:f.get(locale()==='en'?'churchNameEn':'churchNameEs'),accentColor:f.get('accentColor'),logo})});state.bootstrap=await api('/api/public/bootstrap');state.churchProfile=await api('/api/admin/church-profile');applyBranding();toast(t('settings.profileSaved'));closeModal();settings();}catch(err){toast(err.message);}};}

function serviceModal(service){const isNew=!service;service=service||{labelEn:'',labelEs:'',startTime:'10:00',recurrence:{frequency:'weekly',weekday:0}};const template=isNew?{items:[]}:state.services.templates.find(x=>x.id===service.templateId)||{items:[]};let items=JSON.parse(JSON.stringify(template.items||[]));const ministryOptions=()=>state.services.ministries.filter(m=>m.active!==false).map(m=>`<option value="${m.id}">${esc(bilingual(m))}</option>`).join('');function draw(){modal(`<div class="modal-header"><h2>${isNew?t('settings.addServiceTitle'):esc(bilingual(service))}</h2><button class="icon-btn compact" id="close-modal">×</button></div><form id="service-form" class="stack"><div class="field"><label>${t('settings.serviceNameEs')}</label><input class="input" name="labelEs" value="${esc(service.labelEs||service.label||'')}" required></div><div class="field"><label>${t('settings.serviceNameEn')}</label><input class="input" name="labelEn" value="${esc(service.labelEn||service.label||'')}" required></div><div class="row"><div class="field grow"><label>${t('settings.day')}</label><select class="select" name="weekday">${Array.from({length:7},(_,i)=>`<option value="${i}" ${Number(service.recurrence?.weekday)===i?'selected':''}>${esc(weekday(i))}</option>`).join('')}</select></div><div class="field grow"><label>${t('settings.time')}</label><input class="input" name="startTime" type="time" value="${esc(service.startTime)}"></div></div><h3>${t('settings.order')}</h3><p class="tiny muted">${t('settings.sameVolunteerHelp')}</p><div id="program-items" class="stack">${items.map((it,i)=>`<div class="card flat" data-item="${i}"><div class="field"><label>${t('settings.programLineEs')}</label><input class="input item-label-es" value="${esc(it.labelEs||it.label||'')}"></div><div class="field"><label>${t('settings.programLineEn')}</label><input class="input item-label-en" value="${esc(it.labelEn||it.label||'')}"></div><div class="field"><label>${t('settings.ministry')}</label><select class="select item-ministry">${ministryOptions()}</select></div><div class="row"><div class="field grow"><label>${t('settings.peopleNeeded')}</label><select class="select item-count">${[1,2,3,4].map(n=>`<option value="${n}">${n}</option>`).join('')}</select></div><div class="field grow"><label>${t('settings.sameVolunteer')}</label><select class="select item-link"><option value="">${t('settings.independent')}</option>${items.slice(0,i).map((p,j)=>`<option value="${j}">${j+1}. ${esc(locale()==='en'?(p.labelEn||p.label):(p.labelEs||p.label))}</option>`).join('')}</select></div></div><div class="row"><button type="button" class="btn ghost item-up">↑</button><button type="button" class="btn ghost item-down">↓</button><button type="button" class="btn ghost item-remove">${t('settings.remove')}</button></div></div>`).join('')}</div><button type="button" class="btn secondary full" id="add-program-item">${t('settings.addProgramItem')}</button><button class="btn full">${t('settings.saveService')}</button></form>`);$('#close-modal').onclick=closeModal;document.querySelectorAll('[data-item]').forEach((el,i)=>{el.querySelector('.item-ministry').value=items[i].ministryId||'';el.querySelector('.item-count').value=String(items[i].assignmentKeys?.length||1);const previous=items.slice(0,i).findIndex(p=>JSON.stringify(p.assignmentKeys||[])===JSON.stringify(items[i].assignmentKeys||[]));el.querySelector('.item-link').value=items[i].linked&&previous>=0?String(previous):'';const sync=()=>{items[i].labelEs=el.querySelector('.item-label-es').value;items[i].labelEn=el.querySelector('.item-label-en').value;items[i].label=items[i].labelEs;items[i].ministryId=el.querySelector('.item-ministry').value;items[i]._count=Number(el.querySelector('.item-count').value);items[i]._link=el.querySelector('.item-link').value;};el.querySelectorAll('input,select').forEach(x=>x.onchange=sync);el.querySelector('.item-remove').onclick=()=>{items.splice(i,1);draw();};el.querySelector('.item-up').onclick=()=>{if(i){[items[i-1],items[i]]=[items[i],items[i-1]];draw();}};el.querySelector('.item-down').onclick=()=>{if(i<items.length-1){[items[i+1],items[i]]=[items[i],items[i+1]];draw();}};});$('#add-program-item').onclick=()=>{items.push({id:`item_${Date.now()}`,labelEs:t('settings.newItem'),labelEn:'New item',ministryId:state.services.ministries[0]?.id||'',assignmentKeys:[],_count:1,_link:''});draw();};$('#service-form').onsubmit=async e=>{e.preventDefault();document.querySelectorAll('[data-item]').forEach((el,i)=>{items[i].labelEs=el.querySelector('.item-label-es').value;items[i].labelEn=el.querySelector('.item-label-en').value;items[i].label=items[i].labelEs;items[i].ministryId=el.querySelector('.item-ministry').value;items[i]._count=Number(el.querySelector('.item-count').value);items[i]._link=el.querySelector('.item-link').value;});const built=[];items.forEach((it,i)=>{let keys;if(it._link!=='')keys=built[Number(it._link)]?.assignmentKeys||[`item_${i+1}`];else{const n=Math.max(1,it._count||it.assignmentKeys?.length||1);keys=Array.from({length:n},(_,k)=>`item_${i+1}${n>1?`_${k+1}`:''}`);}built.push({id:it.id||`item_${i+1}`,label:it.labelEs,labelEs:it.labelEs,labelEn:it.labelEn,ministryId:it.ministryId,assignmentKeys:keys,linked:it._link!==''});});const f=new FormData(e.target);try{if(isNew)await api('/api/admin/services',{method:'POST',body:JSON.stringify({label:f.get('labelEn'),labelEn:f.get('labelEn'),labelEs:f.get('labelEs'),startTime:f.get('startTime'),recurrence:{frequency:'weekly',weekday:Number(f.get('weekday'))},items:built})});else{await api(`/api/admin/services/${service.id}`,{method:'PUT',body:JSON.stringify({label:f.get('labelEn'),labelEn:f.get('labelEn'),labelEs:f.get('labelEs'),startTime:f.get('startTime'),recurrence:{...service.recurrence,frequency:'weekly',weekday:Number(f.get('weekday'))}})});await api(`/api/admin/templates/${service.templateId}`,{method:'PUT',body:JSON.stringify({items:built})});}toast(t('settings.serviceSaved'));closeModal();settings();}catch(err){toast(err.message);}};}draw();}

async function advancedModal(){try{const s=await api('/api/owner/advanced'),w=s.algorithm?.weights||{};modal(`<div class="modal-header"><h2>${t('settings.advancedTitle')}</h2><button class="icon-btn compact" id="close-modal">×</button></div><div class="attention"><span class="ico">⚙</span><div><strong>${t('settings.ownerOnly')}</strong><div class="small">${t('settings.advancedHelp')}</div></div></div><div class="button-grid"><button class="btn secondary" id="advanced-program-admin">${t('settings.programAdmin')}</button><button class="btn secondary" id="advanced-communications">${t('settings.communications')}</button></div><form id="advanced-form" class="stack"><div class="field"><label>${t('settings.timezone')}</label><input class="input" name="timezone" value="${esc(s.timezone||'America/Chicago')}"></div><div class="field"><label>${t('settings.weekBegins')}</label><select class="select" name="weekStartsOn"><option value="0" ${Number(s.weekStartsOn)===0?'selected':''}>${t('settings.sunday')}</option><option value="1" ${Number(s.weekStartsOn)===1?'selected':''}>${t('settings.monday')}</option></select></div><h3>${t('settings.smartFairWeights')}</h3>${[['roleFairness','settings.roleFairness'],['workloadBalance','settings.workload'],['overallRest','settings.rest'],['futureSpacing','settings.spacing']].map(([k,l])=>`<div class="field"><label>${t(l)}</label><input class="input" type="number" step="0.01" min="0" max="1" name="${k}" value="${Number(w[k]??0)}"></div>`).join('')}<button class="btn full">${t('settings.saveAdvanced')}</button></form>`);$('#close-modal').onclick=closeModal;$('#advanced-program-admin')?.addEventListener('click',()=>{closeModal();programAdminModal();});$('#advanced-communications')?.addEventListener('click',()=>{closeModal();communicationsModal();});$('#advanced-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),weights={roleFairness:Number(f.get('roleFairness')),workloadBalance:Number(f.get('workloadBalance')),overallRest:Number(f.get('overallRest')),futureSpacing:Number(f.get('futureSpacing'))};if(Math.abs(Object.values(weights).reduce((a,b)=>a+b,0)-1)>.001)return toast(t('settings.weightsSum'));try{await api('/api/owner/advanced',{method:'PUT',body:JSON.stringify({timezone:f.get('timezone'),weekStartsOn:Number(f.get('weekStartsOn')),algorithm:{...s.algorithm,weights}})});toast(t('settings.advancedSaved'));closeModal();}catch(err){toast(err.message);}};}catch(e){toast(e.message);}}

