async function uploadImport(endpoint,file){if(!file||!file.size)throw new Error(t('imports.chooseFile'));const payload={file:{fileName:file.name,contentType:file.type||'',base64:await fileToDataUrl(file)}};return api(endpoint,{method:'POST',body:JSON.stringify(payload)});}
