function memberImportModal(){modal(`<div class="modal-header"><h2>${t('imports.membersTitle')}</h2><button class="icon-btn compact" id="close-modal">×</button></div><div class="card flat stack"><strong>${t('imports.memberFormat')}</strong><div class="small">${t('imports.memberRows')}</div><div class="small">${t('imports.memberIdentity')}</div><div class="small">${t('imports.memberAssignmentColumns')}</div><code>Sunday Evening Service - Songs 1</code><code>Sunday Evening Service - Songs 2</code><code>Sunday Evening Service - Sermon</code><div class="small">${t('imports.checkedValues')}</div><div class="tiny muted">${t('imports.scheduleInference')}</div></div><div class="button-grid"><a class="btn secondary" href="/api/owner/members/template?format=csv" target="_blank">${t('imports.templateCsv')}</a><a class="btn secondary" href="/api/owner/members/template?format=excel" target="_blank">${t('imports.templateExcel')}</a></div><form id="member-import-form" class="stack"><div class="field"><label>${t('imports.chooseCsvExcel')}</label><input class="input" type="file" name="file" accept=".csv,.xlsx,.xls,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet,application/vnd.ms-excel" required></div><button class="btn full">${t('imports.import')}</button></form><div id="member-import-result"></div>`);$('#close-modal').onclick=closeModal;$('#member-import-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const f=new FormData(e.target),r=await uploadImport('/api/owner/members/import',f.get('file'));$('#member-import-result').innerHTML=importResultHtml(r);toast(t('imports.complete'));state.people=null;state.services=null;}catch(err){toast(err.message);}finally{b.disabled=false;}};}
