async function reportsModal(){try{const catalog=await api('/api/admin/reports/catalog');const today=new Date().toISOString().slice(0,10);const from=new Date(Date.now()-90*86400000).toISOString().slice(0,10);modal(`<div class="modal-header"><div><div class="eyebrow">Church Hub</div><h2>${l('Leadership Reports','Reportes de Liderazgo')}</h2></div><button class="icon-btn compact" id="close-modal">×</button></div><p class="muted small">${l('Operational reports across worship, communications, visitors, petitions, publications and children.','Reportes operativos de adoración, comunicaciones, visitantes, peticiones, publicaciones y niños.')}</p><div class="row"><div class="field grow"><label>${t('common.from')}</label><input class="input" type="date" id="report-from" value="${from}"></div><div class="field grow"><label>${t('common.to')}</label><input class="input" type="date" id="report-to" value="${today}"></div></div><div class="stack">${catalog.map(r=>`<div class="card flat"><strong>${esc(r.title)}</strong><div class="button-grid" style="margin-top:8px"><button class="btn secondary report-preview" data-report="${esc(r.id)}">${l('Preview','Vista previa')}</button><button class="btn secondary report-export" data-report="${esc(r.id)}" data-format="xlsx">XLSX</button><button class="btn secondary report-export" data-report="${esc(r.id)}" data-format="csv">CSV</button><button class="btn secondary report-export" data-report="${esc(r.id)}" data-format="pdf">PDF</button></div></div>`).join('')}</div><div id="report-preview"></div>`);$('#close-modal').onclick=closeModal;const qs=()=>`?from=${encodeURIComponent($('#report-from').value||'')}&to=${encodeURIComponent($('#report-to').value||'')}`;document.querySelectorAll('.report-export').forEach(b=>b.onclick=()=>{window.open(`/api/admin/reports/${encodeURIComponent(b.dataset.report)}/export${qs()}&format=${encodeURIComponent(b.dataset.format)}`,'_blank');});document.querySelectorAll('.report-preview').forEach(b=>b.onclick=async()=>{const r=await api(`/api/admin/reports/${encodeURIComponent(b.dataset.report)}${qs()}`);const rows=(r.rows||[]).slice(0,12);$('#report-preview').innerHTML=`<div class="section-title"><h3>${esc(r.title)}</h3></div><div class="card flat report-table"><div class="small muted">${rows.length} ${l('rows previewed','filas en vista previa')}</div>${rows.map(x=>`<div class="tiny" style="padding:6px 0;border-bottom:1px solid var(--border)">${Object.entries(x).slice(0,5).map(([k,v])=>`<strong>${esc(k)}:</strong> ${esc(v)}`).join(' · ')}</div>`).join('')}</div>`;});}catch(e){toast(e.message);}}
