async function auditModal(){try{const [rows,p,services]=await Promise.all([api('/api/admin/history?max=160'),state.people||api('/api/admin/people'),api('/api/admin/services')]);state.people=p;const names=new Map(p.members.map(m=>[m.id,m.fullName]));const serviceNames=new Map(services.services.map(x=>[x.id,bilingual(x)]));const serviceTimes=new Map(services.services.map(x=>[x.id,x.startTime||'']));const assignmentLabels=new Map();for(const tpl of services.templates||[])for(const item of tpl.items||[])for(const key of item.assignmentKeys||[])assignmentLabels.set(`${tpl.serviceId}|${key}`,bilingual(item));const ministryNames=new Map(services.ministries.map(x=>[x.id,bilingual(x)]));const decisions=new Map(rows.filter(x=>x.eventType==='scheduler.decision').map(x=>[`${x.programId||''}|${x.assignmentKey||''}`,x]));const cards=rows.filter(x=>x.eventType!=='scheduler.decision').slice(0,120).map(r=>{const decision=decisions.get(`${r.programId||''}|${r.assignmentKey||''}`);const score=decision?.details?.candidates?.find(c=>c.memberId===r.memberId)?.score?.final;const sid=r.serviceId||String(r.programId||'').split('__')[0]||'';return `<div class="card flat audit-card"><div class="row between"><strong>${esc(t(`event.${r.eventType}`)===`event.${r.eventType}`?r.eventType:t(`event.${r.eventType}`))}</strong><span class="tiny muted">${esc(r.occurredAt||'')}</span></div><div class="small"><strong>${esc(names.get(r.memberId)||r.memberId||t('share.unfilled'))}</strong></div><div class="tiny muted">${esc(r.dateISO||'')} · ${esc(serviceNames.get(sid)||sid||'')}${serviceTimes.get(sid)?` · ${esc(fmtTime(serviceTimes.get(sid)))}`:''} · ${esc(assignmentLabels.get(`${sid}|${r.assignmentKey||''}`)||r.assignmentKey||'')} · ${esc(ministryNames.get(r.ministryId)||r.ministryId||'')}</div>${score!=null?`<div class="tiny">${t('settings.schedulerScore')}: <strong>${Number(score).toFixed(1)}</strong></div>`:''}${r.previousMemberId||r.newMemberId?`<div class="tiny">${t('settings.change')}: ${esc(names.get(r.previousMemberId)||r.previousMemberId||'—')} → ${esc(names.get(r.newMemberId)||r.newMemberId||'—')}</div>`:''}${r.eventType==='replacement.requested'?`<div class="tiny">${t('settings.replacementAudit')}: ${r.penaltyEligible?t('common.yes'):t('common.no')}</div>`:''}${r.details?`<details><summary class="tiny">${t('settings.details')}</summary><pre class="audit-json">${esc(JSON.stringify(r.details,null,2))}</pre></details>`:''}</div>`}).join('');modal(`<div class="modal-header"><h2>${t('settings.auditTitle')}</h2><button class="icon-btn compact" id="close-modal">×</button></div><p class="muted small">${t('settings.auditDetailedHelp')}</p><div class="button-grid audit-export-grid"><a class="btn secondary" href="/api/admin/history/export?format=csv" target="_blank">CSV</a><a class="btn secondary" href="/api/admin/history/export?format=excel" target="_blank">Excel</a><a class="btn secondary" href="/api/admin/history/export?format=pdf" target="_blank">PDF</a></div><div class="stack">${cards||`<div class="empty">${t('settings.noAudit')}</div>`}</div>`);$('#close-modal').onclick=closeModal;}catch(e){toast(e.message);}}
async function communicationsModal(){try{const [status,members]=await Promise.all([api('/api/owner/communications/status'),api('/api/owner/communications/members')]);const options=members.map(m=>`<option value="${esc(m.id)}">${esc(m.fullName)}${m.email?` · ${esc(m.email)}`:''}${m.phone?` · ${esc(m.phone)}`:''}</option>`).join('');const last=status.lastTestResult||null;modal(`<div class="modal-header"><h2>${t('settings.communications')}</h2><button class="icon-btn compact" id="close-modal">×</button></div><div class="card flat stack"><div class="row between"><span>${t('communications.emailSender')}</span><strong>${esc(status.email?.sender||t('common.none'))}</strong></div><div class="row between"><span>${t('communications.smsSender')}</span><strong>${esc(status.sms?.fromNumber||t('common.none'))}</strong></div><div class="row between"><span>${t('communications.pushStatus')}</span><strong>${status.push?.enabled?esc(t('communications.configured')):esc(t('communications.notConfigured'))}</strong></div><div class="row between"><span>${t('communications.lastResult')}</span><strong>${last?`${esc(last.channel)} · ${esc(last.status)}`:t('common.none')}</strong></div></div><form id="comm-test-form" class="stack"><div class="field"><label>${t('communications.testMember')}</label><select class="select" name="memberId" required><option value="">—</option>${options}</select></div><div class="pill-tabs"><label class="pill active"><input type="radio" name="channel" value="email" checked hidden> ${t('communications.email')}</label><label class="pill"><input type="radio" name="channel" value="sms" hidden> ${t('communications.sms')}</label><label class="pill"><input type="radio" name="channel" value="push" hidden> ${t('communications.push')}</label></div><div class="field"><label>${t('communications.subject')}</label><input class="input" name="subject" value="${esc(state.bootstrap?.church?.churchName||'Church')} test"></div><div class="field"><label>${t('communications.message')}</label><textarea class="textarea" name="message">${t('communications.testMessage')}</textarea></div><button class="btn full">${t('communications.sendTest')}</button></form><div class="section-title"><h3>${t('communications.recent')}</h3></div><div class="stack">${(status.lastResults||[]).slice(0,8).map(r=>`<div class="card flat"><div class="row between"><strong>${esc(String(r.channel||'').toUpperCase())}</strong><span class="badge ${r.status==='failed'?'warn':'success'}">${esc(r.status||'')}</span></div><div class="small">${esc(r.recipient||'')}</div><div class="tiny muted">${esc(r.occurredAt||'')}</div></div>`).join('')||`<div class="empty">${t('communications.noResults')}</div>`}</div>`);$('#close-modal').onclick=closeModal;document.querySelectorAll('#comm-test-form input[name=channel]').forEach(r=>r.onchange=()=>document.querySelectorAll('#comm-test-form .pill').forEach(x=>x.classList.toggle('active',x.querySelector('input').checked)));$('#comm-test-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const result=await api('/api/owner/communications/test',{method:'POST',body:JSON.stringify({memberId:f.get('memberId'),channel:f.get('channel'),subject:f.get('subject'),message:f.get('message')})});toast(`${t('communications.sent')}: ${result.status||result.messageId||'OK'}`);closeModal();communicationsModal();}catch(err){toast(err.message);}};}catch(e){toast(e.message);}}

